def comparacoes_buscas(lista, alvo):
    ordenada = sorted(lista)
    linear = 0
    for valor in lista:
        linear += 1
        if valor == alvo:
            break

    binaria = 0
    inicio, fim = 0, len(ordenada) - 1
    while inicio <= fim:
        binaria += 1
        meio = (inicio + fim) // 2
        if ordenada[meio] == alvo:
            break
        if ordenada[meio] < alvo:
            inicio = meio + 1
        else:
            fim = meio - 1

    return linear, binaria

print(comparacoes_buscas([8, 3, 5, 1, 9], 9))
